import { expect } from 'chai';
import { validateEmail } from '../../src/validator.email';

suite('validator.email', () => {
  test('validates email domain correctly', () => {
    // Valid email
    expect(validateEmail('test@company.com')).to.be.true;

    // Invalid email (wrong domain)
    expect(validateEmail('test@wrongdomain.com')).to.be.false;
  });

  test('rejects emails without @ symbol', () => {
    expect(validateEmail('testcompany.com')).to.be.false;
  });

  test('rejects emails without domain part', () => {
    expect(validateEmail('test@.com')).to.be.false;
  });
});

